import static cn.iocoder.atlas.module.infra.ontology.OntologyModelingPermissionContracts.*;

/** All parents arise through real prepare/confirm/claim/journal/finish. IAM and native boundary are fixtures. */
class RemainingFivePhase2Test extends RemainingFiveContinuationTest {
 String first,firstHash,second;Map<String,Object> firstRow;final String proof="sha256:"+"7".repeat(64);
 void twoParents()throws Exception{clock=Clock.fixed(Instant.now(),ZoneOffset.UTC);partial();first=child;request();effect=(a,p,g)->{if(p.capability().equals("MODEL_VALIDATE"))throw new IllegalStateException("LOCAL_PREFETCH_CLASSIFY_DENIED_BEFORE_DISPATCH");return transport(a,p,g);};assertTrue(permissions.executeOnce(first));assertEquals("REQUIRES_OPERATOR",row(first).get("state"));var steps=permissions.result(p1,first,null).steps();assertEquals("VERIFIED",steps.getFirst().state());assertTrue(steps.subList(1,5).stream().allMatch(x->x.state().equals("NOT_STARTED")&&x.requestHash()==null&&x.nativeId()==null&&x.evidenceRef()==null));firstRow=row(first);firstHash=hash(first);clock=Clock.offset(clock,Duration.ofSeconds(65));permissions=newPermissionStore();effect=this::transport;second=UUID.nameUUIDFromBytes(("atlas:m13:remaining-five:phase2:"+parent+":"+first).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 QualificationRun phase2(){return permissions.requestRemainingFivePhase2(parent,parentHash,firstHash,proof);}
 void bothUnchanged(){unchanged();assertEquals(firstHash,hash(first));assertEquals(firstRow.get("journal_json"),row(first).get("journal_json"));assertEquals(firstRow.get("snapshot_json"),row(first).get("snapshot_json"));}
 @Test void twoParentsFiveOwnStepsAndPermanentOnceSucceed()throws Exception{assertThrows(IllegalStateException.class,()->RemainingFivePhase2OnceBootstrap.main(new String[0]));twoParents();int previous=childEffects.get();var ready=phase2();assertEquals(second,ready.runId());assertEquals("remaining-five-phase2:qualification-key",ready.operationKey());var safe=JdbcOntologyModelingPermissionStore.receiptMap(journal(second).get("receipts"));assertEquals(7,safe.size());assertTrue(safe.values().stream().noneMatch(x->x.containsKey("lease")));assertEquals(5,safe.values().stream().filter(x->"PARENT_VERIFIED_NATIVE_FACT".equals(x.get("sourceKind"))).count());var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);var a=pool.submit(()->{start.await();return permissions.executeOnce(second);});var b=pool.submit(()->{start.await();return newPermissionStore().executeOnce(second);});start.countDown();assertEquals(1,(a.get(10,TimeUnit.SECONDS)?1:0)+(b.get(10,TimeUnit.SECONDS)?1:0));pool.shutdownNow();var result=permissions.result(p1,second,null);assertEquals("SUCCEEDED",result.state());assertEquals(5,result.steps().size());assertTrue(result.steps().stream().allMatch(x->x.state().equals("VERIFIED")));assertEquals(previous+5,childEffects.get());assertEquals(11,permissions.get(p1,"2","om-locked").qualifications().stream().filter(x->x.state().equals("VERIFIED")).count());assertEquals(second,phase2().runId());assertFalse(permissions.executeOnce(second));assertEquals(previous+5,childEffects.get());assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(parent,parentHash,firstHash,"sha256:"+"8".repeat(64)));assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(second,hash(second),firstHash,proof));assertThrows(OntologyApiException.class,()->qualification());bothUnchanged();}
 @Test void doubleParentCurrentCutAndNonExactPhase1NeverSend()throws Exception{twoParents();int previous=childEffects.get();assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(parent,"sha256:"+"0".repeat(64),firstHash,proof));assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(parent,parentHash,"sha256:"+"0".repeat(64),proof));Clock saved=clock;clock=Clock.offset(clock,Duration.ofSeconds(-65));var liveLease=newPermissionStore();assertThrows(OntologyApiException.class,()->liveLease.requestRemainingFivePhase2(parent,parentHash,firstHash,proof));clock=saved;String snapshot=(String)row(first).get("snapshot_json");var invalidSnapshot=JdbcOntologyModelingPermissionStore.read(snapshot);var invalidCut=JdbcOntologyModelingPermissionStore.object(invalidSnapshot.get("cut"));invalidCut.put("configurationVersion",999);invalidSnapshot.put("cut",invalidCut);jdbc.update("UPDATE ontology_modeling_qualification SET snapshot_json=? WHERE id=?",JdbcOntologyModelingPermissionStore.write(invalidSnapshot),first);assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(parent,parentHash,hash(first),proof));jdbc.update("UPDATE ontology_modeling_qualification SET snapshot_json=? WHERE id=?",snapshot,first);var raw=(String)row(first).get("journal_json");var changed=journal(first);var states=new ArrayList<>(JdbcOntologyModelingPermissionStore.stepResults(changed.get("steps")));var old=states.get(1);states.set(1,new StepResult(old.stepId(),old.capability(),"DISPATCHED","sha256:"+"a".repeat(64),null,null,"synthetic negative tampering only"));changed.put("steps",states);jdbc.update("UPDATE ontology_modeling_qualification SET journal_json=? WHERE id=?",JdbcOntologyModelingPermissionStore.write(changed),first);assertThrows(OntologyApiException.class,()->permissions.requestRemainingFivePhase2(parent,parentHash,hash(first),proof));jdbc.update("UPDATE ontology_modeling_qualification SET journal_json=? WHERE id=?",raw,first);phase2();jdbc.update("UPDATE ontology_modeling_qualification SET journal_json=? WHERE id=?",raw+" ",first);assertFalse(permissions.executeOnce(second));assertEquals(previous,childEffects.get());jdbc.update("UPDATE ontology_modeling_qualification SET journal_json=? WHERE id=?",raw,first);bothUnchanged();var f=new RemainingFivePhase2Test();f.setup();f.twoParents();f.phase2();int n=f.childEffects.get();f.jdbc.update("UPDATE ontology_modeling_access SET version=version+1");assertFalse(f.permissions.executeOnce(f.second));assertEquals(n,f.childEffects.get());f.bothUnchanged();}
 @Test void collisionOtherInflightAndLateLossKeepKnownAck()throws Exception{twoParents();int previous=childEffects.get();String other=UUID.randomUUID().toString();jdbc.update("INSERT INTO ontology_modeling_qualification SELECT ?,tenant_id,space_id,project_id,account_id,instance_id,initiator,?,plan_id,plan_hash,'READY',row_version,snapshot_json,journal_json,created_at,updated_at FROM ontology_modeling_qualification WHERE id=?",other,"other-live",parent);assertThrows(OntologyApiException.class,this::phase2);jdbc.update("DELETE FROM ontology_modeling_qualification WHERE id=?",other);jdbc.update("INSERT INTO ontology_modeling_qualification SELECT ?,tenant_id,space_id,project_id,account_id,instance_id,initiator,?,plan_id,plan_hash,'SUCCEEDED',row_version,snapshot_json,journal_json,created_at,updated_at FROM ontology_modeling_qualification WHERE id=?",second,"foreign-id-collision",parent);assertThrows(OntologyApiException.class,this::phase2);jdbc.update("DELETE FROM ontology_modeling_qualification WHERE id=?",second);phase2();effect=(ad,p,g)->{g.current();String request=OntologyCanonicalJson.hash("known-phase2-ack");g.beforeSend(request);childEffects.incrementAndGet();jdbc.update("UPDATE ontology_scope_grant SET active=0 WHERE account_id='2'");g.acknowledged(request,null,Map.of("status",200,"responseHash",OntologyCanonicalJson.hash("already-returned")));g.current();throw new AssertionError("REVOKED_MUST_BLOCK");};assertTrue(permissions.executeOnce(second));assertEquals("UNKNOWN",row(second).get("state"));var states=JdbcOntologyModelingPermissionStore.stepResults(journal(second).get("steps"));assertEquals("ACKNOWLEDGED",states.getFirst().state());assertTrue(states.stream().noneMatch(x->x.state().equals("VERIFIED")));assertFalse(newPermissionStore().executeOnce(second));assertEquals(previous+1,childEffects.get());bothUnchanged();}
}
